-- Report ID : RPT_073
-- Report    : Ti-Hi Mismatch Pack Component
-- Module    : Replenishment
-- Source    : Oracle RMS / MFCS RDS Views
-- Generated : Extracted from DVA file
--------------------------------------------------------------------------------

SELECT     TRUNC(SYSDATE)                                        AS report_date,      pim.DEPT                                              AS dept_no,     d.DEPT_NAME                                           AS dept_name,     pim.CLASS                                             AS class_no,     c.CLASS_NAME                                          AS class_name,     pim.SUBCLASS                                          AS subclass_no,     sc.SUB_NAME                                           AS subclass_name,      pim.ITEM                                              AS pack_item_id,     pim.ITEM_DESC                                         AS pack_item_desc,     pim.PACK_IND                                          AS pack_ind,     pim.STATUS                                            AS pack_status,      pi.ITEM                                               AS component_item_id,     cim.ITEM_DESC                                         AS component_item_desc,     pi.PACK_QTY                                           AS component_qty_in_pack,     cim.STANDARD_UOM                                      AS component_uom,      pisc.SUPPLIER                                         AS supplier_id,     sp.SUP_NAME                                           AS supplier_name,     pisc.ORIGIN_COUNTRY_ID                                AS origin_country,      pisc.TI                                               AS pack_ti,     pisc.HI                                               AS pack_hi,     pisc.SUPP_PACK_SIZE                                   AS pack_supp_pack_size,     pisc.INNER_PACK_SIZE                                  AS pack_inner_pack_size,     NVL(pisc.TI, 0) * NVL(pisc.HI, 0)         * NVL(pisc.SUPP_PACK_SIZE, 1)                     AS pack_pallet_multiple,      cisc.TI                                               AS comp_ti,     cisc.HI                                               AS comp_hi,     cisc.SUPP_PACK_SIZE                                   AS comp_supp_pack_size,     cisc.INNER_PACK_SIZE                                  AS comp_inner_pack_size,     NVL(cisc.TI, 0) * NVL(cisc.HI, 0)         * NVL(cisc.SUPP_PACK_SIZE, 1)                     AS comp_pallet_multiple,      NVL(pisc.TI, 0) - NVL(cisc.TI, 0)                    AS ti_variance,     NVL(pisc.HI, 0) - NVL(cisc.HI, 0)                    AS hi_variance,     (NVL(pisc.TI, 0) * NVL(pisc.HI, 0) * NVL(pisc.SUPP_PACK_SIZE, 1))     - (NVL(cisc.TI, 0) * NVL(cisc.HI, 0) * NVL(cisc.SUPP_PACK_SIZE, 1))                                                           AS pallet_multiple_variance,      CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL         THEN 'PACK TI-HI NOT SET'         WHEN cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'COMPONENT TI-HI NOT SET'         WHEN pisc.TI != cisc.TI AND pisc.HI != cisc.HI         THEN 'BOTH TI AND HI MISMATCH'         WHEN pisc.TI != cisc.TI AND pisc.HI  = cisc.HI         THEN 'TI MISMATCH ONLY'         WHEN pisc.TI  = cisc.TI AND pisc.HI != cisc.HI         THEN 'HI MISMATCH ONLY'         ELSE 'MISMATCH DETECTED'     END                                                   AS mismatch_type,      CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL           OR cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'HIGH - Missing Ti-Hi prevents pallet calculation'         WHEN ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0)) > 5           OR ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) > 5         THEN 'HIGH - Large variance impacts warehouse slotting'         WHEN ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0)) BETWEEN 2 AND 5           OR ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) BETWEEN 2 AND 5         THEN 'MEDIUM - Moderate variance, review required'         ELSE 'LOW - Minor variance, monitor'     END                                                   AS severity,      ril.LOCATION                                          AS location_id,     il.LOC_TYPE                                           AS loc_type,     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS loc_type_desc,     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS location_name,     il.STATUS                                             AS item_loc_status,     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS item_loc_status_desc,      ril.REPL_METHOD                                       AS repl_method,     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS repl_method_desc,     ril.STOCK_CAT                                         AS stock_category,     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS stock_category_desc,     ril.REPL_ORDER_CTRL                                   AS order_control,     ril.NON_SCALING_IND                                   AS scaling_exempt_ind,     ril.MAX_SCALE_VALUE                                   AS max_scale_amount,     ril.PRIMARY_PACK_NO                                   AS primary_repl_pack,      ils.STOCK_ON_HAND                                     AS pack_current_soh,     ils.AV_COST                                           AS pack_wac,     cils.STOCK_ON_HAND                                    AS comp_current_soh,      CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL         THEN 'Set TI and HI on pack ITEM_SUPP_COUNTRY to match component values'         WHEN cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'Set TI and HI on component ITEM_SUPP_COUNTRY - pack values exist'         WHEN pisc.TI != cisc.TI AND pisc.HI != cisc.HI         THEN 'Align both TI and HI on pack to match component: TI='              || cisc.TI || ', HI=' || cisc.HI         WHEN pisc.TI != cisc.TI         THEN 'Correct pack TI from ' || pisc.TI              || ' to ' || cisc.TI || ' to match component'         WHEN pisc.HI != cisc.HI         THEN 'Correct pack HI from ' || pisc.HI              || ' to ' || cisc.HI || ' to match component'         ELSE 'Verify configuration'     END                                                   AS recommended_action,      pisc.LEAD_TIME                                        AS pack_lead_time,     pisc.PICKUP_LEAD_TIME                                 AS pack_pickup_lt  FROM     MFCS_RDS.RDS_WV_ITEM_MASTER              pim      JOIN  MFCS_RDS.RDS_WV_PACKITEM           pi    ON  pim.ITEM        = pi.PACK_NO      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER        cim   ON  pi.ITEM         = cim.ITEM      JOIN  MFCS_RDS.RDS_WV_DEPS               d     ON  pim.DEPT        = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS              c     ON  pim.DEPT        = c.DEPT                                                    AND  pim.CLASS       = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc    ON  pim.DEPT        = sc.DEPT                                                    AND  pim.CLASS       = sc.CLASS                                                    AND  pim.SUBCLASS    = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY pisc  ON  pim.ITEM        = pisc.ITEM                                                    AND  pisc.PRIMARY_SUPP_IND    = 'Y'                                                    AND  pisc.PRIMARY_COUNTRY_IND = 'Y'      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY cisc  ON  pi.ITEM         = cisc.ITEM                                                    AND  cisc.SUPPLIER  = pisc.SUPPLIER                                                    AND  cisc.PRIMARY_SUPP_IND    = 'Y'                                                    AND  cisc.PRIMARY_COUNTRY_IND = 'Y'      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC      ril  ON  pim.ITEM        = ril.ITEM                                                    AND  ril.REPL_METHOD IS NOT NULL      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC            il  ON  ril.ITEM        = il.ITEM                                                    AND  ril.LOCATION   = il.LOC                                                    AND  ril.LOC_TYPE   = il.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_SUPS            sp  ON  pisc.SUPPLIER   = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE           st  ON  ril.LOCATION    = st.STORE                                                    AND  il.LOC_TYPE    = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh  ON  ril.LOCATION    = wh.WH                                                    AND  il.LOC_TYPE    = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH   ils  ON  pim.ITEM        = ils.ITEM                                                    AND  ril.LOCATION   = ils.LOC                                                    AND  ils.LOC_TYPE   = ril.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils  ON  pi.ITEM         = cils.ITEM                                                    AND  ril.LOCATION   = cils.LOC                                                    AND  cils.LOC_TYPE  = ril.LOC_TYPE  WHERE     pim.PACK_IND        = 'Y'     AND ril.REPL_METHOD IS NOT NULL     AND il.STATUS       IN ('A', 'C')     AND pim.STATUS       = 'A'     AND (         NVL(pisc.TI, -999) != NVL(cisc.TI, -999)         OR NVL(pisc.HI, -999) != NVL(cisc.HI, -999)     )  ORDER BY     CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL           OR cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'HIGH - Missing Ti-Hi prevents pallet calculation'         WHEN ABS(NVL(pisc.TI,0)-NVL(cisc.TI,0)) > 5           OR ABS(NVL(pisc.HI,0)-NVL(cisc.HI,0)) > 5         THEN 'HIGH - Large variance impacts warehouse slotting'         WHEN ABS(NVL(pisc.TI,0)-NVL(cisc.TI,0)) BETWEEN 2 AND 5           OR ABS(NVL(pisc.HI,0)-NVL(cisc.HI,0)) BETWEEN 2 AND 5         THEN 'MEDIUM - Moderate variance, review required'         ELSE 'LOW - Minor variance, monitor'     END,     ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0))         + ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) DESC,     d.DEPT_NAME,     pim.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END